#!/bin/sh
# Creates .env with strong random secrets. Safe to run twice: it never overwrites an existing .env.
set -eu
cd "$(dirname "$0")/.."
if [ -f .env ]; then echo ".env already exists - leaving it alone."; exit 0; fi
rand() { LC_ALL=C tr -dc 'A-Za-z0-9' </dev/urandom | head -c "$1"; }
admin_pw="$(rand 6)-$(rand 6)-$(rand 6)"
cat > .env <<ENV
# Generated by scripts/init-env.sh - keep this file private (it is in .gitignore).
POSTGRES_PASSWORD=$(rand 32)
OWNER_DB_PASSWORD=$(rand 32)
APP_DB_PASSWORD=$(rand 32)
READONLY_DB_PASSWORD=$(rand 32)
JWT_SECRET=$(rand 64)
# Browser cookies need HTTPS when this is true. Leave false only for http://localhost.
COOKIE_SECURE=false
CORS_ORIGINS=["http://localhost:8080"]
BOOTSTRAP_ADMIN_EMAIL=admin@example.com
BOOTSTRAP_ADMIN_PASSWORD=$admin_pw
WEB_PORT=8080
ENV
chmod 600 .env
echo "Created .env"
echo "First admin login:  admin@example.com  /  $admin_pw"
echo "(Change it after signing in: Account > Change password.)"
